"Sự kiện CIO đánh dấu khẩn được đo theo mục tiêu ≤ 30 phút, từ tin sớm nhất đến lúc lần áp dụng có hiệu lực cho RM. Hệ thống đề xuất khẩn khi NHNN quyết định lãi suất điều hành hoặc biên độ tỷ giá, hoặc khi một yếu tố biến động quá 3 lần độ lệch chuẩn trong ngày — cách hiểu của chúng tôi cho tới khi ngân hàng định nghĩa.":"Events the CIO marks urgent are measured against a ≤ 30-minute target, from the earliest news to when the application takes effect for RMs. The system suggests urgent when the SBV decides the policy rate or the exchange-rate band, or when a factor moves more than 3 standard deviations in a day — our reading until the bank defines it.",
