"Đọc từ những gì hệ thống ghi lại: tin và sự kiện bị bỏ sót, thời gian CIO xem trước khi duyệt, thời gian từ tin đến RM, tốc độ hộp tin và Agent, mức sẵn sàng trong giờ làm việc.":"Read from what the system records: missed news and events, how long the CIO looks before approving, time from news to RM, inbox and agent speed, availability during working hours.",
"Bỏ sót":"Missed",
"BRD-RULE-MEAS-03 · theo tháng, kèm nguyên nhân":"BRD-RULE-MEAS-03 · monthly, with causes",
"Tin quan trọng (mức liên quan “cao” — cách hiểu của chúng tôi, Q-07) không thành sự kiện; sự kiện không đến được các gia đình.":"Important news (“high” relevance — our reading, Q-07) that did not become an event; events that did not reach families.",
"Duyệt cho có":"Rubber-stamp approvals",
"BRD-RULE-MEAS-05 · theo tháng":"BRD-RULE-MEAS-05 · monthly",
"Thời gian CIO xem từ lúc nhận định sẵn sàng đến lúc duyệt, và tỷ lệ duyệt không sửa gì. “Duyệt rất nhanh” là dưới {0} phút — ngưỡng của chúng tôi, không phải của BRD.":"How long the CIO looks from when a view is ready until approval, and the share approved with no edits. “Approved very fast” is under {0} minutes — our threshold, not the BRD's.",
"Từ tin đến RM":"From news to RM",
"BRD-KPI-01 · BRD-RULE-WF-09 · mục tiêu ≤ {0} giờ":"BRD-KPI-01 · BRD-RULE-WF-09 · target ≤ {0} h",
"Từ lúc tin sớm nhất của sự kiện được đăng đến lúc lần áp dụng có hiệu lực cho RM. Tin khẩn (mục tiêu ≤ {0} phút) là sự kiện CIO đánh dấu khẩn kèm lý do; hệ thống đề xuất khẩn khi NHNN quyết định lãi suất điều hành, biên độ tỷ giá, hoặc khi một yếu tố biến động quá 3 lần độ lệch chuẩn trong ngày —":"From when the event's earliest news is published to when the application takes effect for RMs. Urgent news (target ≤ {0} minutes) is an event the CIO marks urgent with a reason; the system suggests urgent when the SBV decides the policy rate or the exchange-rate band, or when a factor moves more than 3 standard deviations in a day —",
"Đề xuất":"Suggested",
"cách hiểu của chúng tôi cho tới khi ngân hàng định nghĩa. {0} sự kiện đã đánh dấu khẩn, {1} sự kiện được đề xuất.":"our reading until the bank defines it. {0} events marked urgent, {1} events suggested.",
"Tin quan trọng được thu thập":"Important news collected",
"BRD-KPI-02 · mục tiêu ≥ {0}":"BRD-KPI-02 · target ≥ {0}",
"BRD-KPI-02 · mục tiêu ≥":"BRD-KPI-02 · target ≥",
"Tin quan trọng: câu chuyện về các yếu tố của mô hình mà nguồn đối chiếu độc lập ({0}) đưa từ ít nhất hai báo. Đã thu thập: trong vòng một ngày, Hộp tin có tin cùng câu chuyện.":"Important news: stories about the model's factors that the independent cross-check source ({0}) carries from at least two outlets. Collected: within one day, the News inbox has news on the same story.",
"cách hiểu của chúng tôi cho tới khi ngân hàng định nghĩa. Cột “Báo đang theo dõi” chỉ tính câu chuyện có ít nhất một báo thuộc danh sách trắng.":"our reading until the bank defines it. The “Outlets followed” column only counts stories with at least one outlet on the allow list.",
"Khuyến nghị có người duyệt và nhật ký":"Recommendations with an approver and a log",
"BRD-KPI-05 · mục tiêu {0}":"BRD-KPI-05 · target {0}",
"BRD-KPI-05 · mục tiêu":"BRD-KPI-05 · target",
"Khuyến nghị đã đưa ra: lần áp dụng đã hiệu lực (RM và khách đọc tác động), bản tin đã duyệt, đề xuất của khách RM đã duyệt. Mỗi khuyến nghị cần một người duyệt (nhân viên, không phải agent, khác người soạn) và các dòng duyệt trong chuỗi nhật ký.":"Recommendations given: applications that took effect (RMs and clients read the impact), approved newsletters, client proposals the RM approved. Each recommendation needs one approver (a staff member, not an agent, not the author) and the approval rows in the audit chain.",
"cách hiểu của chúng tôi. Đề xuất RM duyệt trước ngày 16/10/2026 không ghi người duyệt nên được tính là thiếu.":"our reading. RM proposals approved before 16/10/2026 recorded no approver, so they count as missing.",
"Liên hệ bắt đầu từ tín hiệu hệ thống":"Contacts started from a system signal",
"BRD-KPI-06 · mục tiêu ≥ {0}":"BRD-KPI-06 · target ≥ {0}",
"BRD-KPI-06 · mục tiêu ≥":"BRD-KPI-06 · target ≥",
"RM ghi mỗi lần liên hệ khách ở Tổng quan (Ghi liên hệ), kèm tín hiệu khởi đầu (gia đình cần xem trước, việc theo mục tiêu) hoặc không. Tín hiệu được kiểm khi ghi. Hành vi thật của RM chỉ đo được khi thí điểm.":"RMs log each client contact on the Overview (Log contact), with the signal that started it (family to review, goal task) or none. The signal is checked when logged. Real RM behaviour can only be measured in a pilot.",
"Khách mở cảnh báo mức cao":"Clients opening high-level alerts",
"BRD-KPI-07 · mục tiêu ≥ {0}":"BRD-KPI-07 · target ≥ {0}",
"BRD-KPI-07 · mục tiêu ≥":"BRD-KPI-07 · target ≥",
"Không gửi gì ra ngoài: cảnh báo đến khách trong ứng dụng, là mục mức cao của “Điều đáng chú ý” (chuông, Toàn cảnh). Đến: lần đầu chính khách xem thấy. Mở: khách bấm vào mục. Tháng gần nhất còn đang tính. Hành vi thật của khách chỉ đo được khi thí điểm.":"Nothing is sent outside: alerts reach the client in the app, as the high-level items of “Worth noting” (bell, Big picture). Reached: the first time the client sees it. Opened: the client clicks the item. The latest month is still being counted. Real client behaviour can only be measured in a pilot.",
