"Cú sốc lõi × mức đã vào giá (chưa ×{0}, một phần ×{1}, hết ×{2}). Các yếu tố khác suy ra bằng kỳ vọng có điều kiện. Dải gồm biến động còn lại × độ dài kỳ hạn, bất định cỡ cú sốc ({3} cỡ), rủi ro riêng từng mã.":"Core shock × how much is priced in (not yet ×{0}, partly ×{1}, fully ×{2}). The other factors are inferred by conditional expectation. The range includes residual volatility × horizon length, shock-size uncertainty ({3} size), and each ticker's own risk.",
"Chế độ căng thẳng: tương quan ×1,4, cắt ±0,85, ghi đè bốn cặp, nắn về xác định dương. Lần nắn này đổi tương quan nhiều nhất {0} (trị riêng nhỏ nhất trước khi nắn {1}).":"Stressed regime: correlations ×1.4, clipped at ±0.85, four pairs overridden, repaired to positive definite. This repair changes a correlation by at most {0} (smallest eigenvalue before repair {1}).",
