"Nguồn tin hay chuỗi thị trường không lấy được, agent lỗi, chuỗi nhật ký gãy, gói từ vùng AI bị từ chối, không gửi được vùng AI. Một cảnh báo cho mỗi việc: lỗi lại thì đếm thêm, chạy lại được thì tự hết. “Đã xem” được ghi vào nhật ký.":"A news source or market series could not be fetched, an agent failed, the audit chain broke, an AI zone package was rejected, the AI zone could not be reached. One alert per problem: another failure adds to the count, a successful rerun clears it. “Seen” is written to the log.",
