"Lỗi: số lần lấy có ít nhất một nguồn lỗi. “—”: lần lấy trước {0} không ghi số này (không có số liệu, không phải 0). Đọc = quá cũ + trùng + mới. Trễ: trung vị từ lúc báo đăng đến lúc ta thu. Tác động danh mục: tin thuộc sự kiện đã duyệt và áp dụng lên ít nhất một gia đình; “nháp”: tin mà bản nháp thử nghiệm (chưa ai duyệt) sẽ chạm tới gia đình; cả hai tăng sau ngày thu.":"Errors: fetches with at least one source failing. “—”: fetches before {0} did not record this number (no data, not 0). Read = too old + duplicate + new. Delay: median from publication to collection. Portfolio impact: news in an approved event applied to at least one family; “draft”: news a trial draft (not approved) would bring to a family; both grow after the collection day.",
