"Tin cũ của bốn báo (VnEconomy, VnExpress, CafeF, Vietstock) chạy lại từng buổi sáng qua đúng các bước của thử nghiệm, cùng mô hình, rồi chấm như trực tiếp với diễn biến thị trường đến nay. Mô hình chỉ biết đến khoảng tháng 6/2026, không biết kết quả sau đó; agent chỉ đọc tin và danh mục yếu tố, không có số liệu thị trường. Không ai duyệt: việc duyệt không đổi điểm.":"Old news from four papers (VnEconomy, VnExpress, CafeF, Vietstock) replayed morning by morning through exactly the trial's steps, with the same model, then scored like live against the market up to now. The model only knows up to about June 2026, not what came after; the agent only reads the news and the factor list, with no market data. No one approves: approval does not change the score.",
"Khác với trực tiếp":"Different from live",
