"Tin tháng 7 của bốn báo (VnEconomy, VnExpress, CafeF, Vietstock) được chạy lại từng buổi sáng qua đúng các bước của thử nghiệm, rồi chấm với diễn biến thị trường đến nay — câu trả lời nhanh cho kỳ 3 tháng. Hai mô hình chỉ biết đến khoảng tháng 6/2026 và không biết kết quả tháng 7–9; agent chỉ đọc tin và danh mục yếu tố, không có số liệu thị trường. Một lần đọc đầu, chưa phải bằng chứng: {0} sự kiện trong ba tuần của một mùa hè.":"July news from four papers (VnEconomy, VnExpress, CafeF, Vietstock) replayed morning by morning through exactly the trial's steps, then scored against the market up to now — a quick answer for the 3-month horizon. Both models only know up to about June 2026 and do not know the July–September results; the agent only reads the news and the factor list, with no market data. A first read, not yet proof: {0} events in three weeks of one summer.",
"Các dự báo không độc lập:":"The forecasts are not independent:",
"mọi dự báo tháng 7 được chấm trên cùng một diễn biến (VN-Index giảm từ tháng 7 đến tháng 10), nên tỷ lệ đúng của VN-Index là một lần đoán đúng một xu hướng.":"every July forecast is scored on the same move (VN-Index fell from July to October), so the VN-Index hit rate is one right guess of one trend.",
