"Mỗi số đi kèm số lần đã chấm. Một tuần buổi sáng là mẫu nhỏ: tỷ lệ chỉ để xem xu hướng, chưa đủ để kết luận (cần ≥ 24 lần). Gốc tính là giá đóng cửa trước khi agent chạy. Ý kiến của công ty chứng khoán sẽ là phân khúc thứ tư khi có nguồn.":"Each number comes with how many times it was scored. A week of mornings is a small sample: the rates show the trend only and are not enough to conclude (needs ≥ 24 times). The base is the close before the agent ran. Brokers' views will be a fourth segment once there is a source.",
