"“Mua” khi mức biến động kỳ vọng lớn hơn một phần tư biến động thông thường của kỳ, “bán” khi nhỏ hơn âm mức đó, còn lại “giữ”; đúng khi thị trường đi theo (giữ: đi không quá mức đó).":"“Buy” when the expected move is more than a quarter of the horizon's typical move, “sell” when below minus that, otherwise “hold”; right when the market follows (hold: moves no more than that).",
