"Hiểu câu hỏi, gọi công cụ của vai trò qua nhiều bước, dừng chờ người xác nhận trước khi ghi, trả lời kèm trang, nguồn và ngày (A2).":"Understands the question, calls the role's tools over several steps, waits for the person to confirm before writing, answers with page, source and date (A2).",
