"Khi chưa có mô hình hoặc mô hình lỗi trước công cụ đầu: chọn một công cụ theo từ khoá (Copilot), để sản phẩm không dừng vì AI (NFR-03).":"With no model, or a model error before the first tool: picks one tool by keyword (Copilot), so the product never stops because of AI (NFR-03).",
"câu hỏi đã che tên và số":"the question with names and numbers masked",
"Chạy đúng đồ thị mà các trang chạy: tổng quan, dòng tiền, tác động, đề xuất, sự kiện, cảnh báo…; đếm, lọc bằng truy_van trên phòng dữ liệu chỉ đọc của vai trò (ADR-0040).":"Runs the same graphs the pages run: overview, cash flow, impact, proposals, events, alerts…; counts and filters with truy_van on the role's read-only data room (ADR-0040).",
"Nhớ, sửa, quên những gì người dùng bảo và xác nhận; tìm lại hội thoại cũ (A4).":"Remembers, edits and forgets what the user says and confirms; finds old conversations (A4).",
"Đặt, liệt kê, huỷ một điều kiện cần báo: mức của chuỗi thị trường, hoặc một chủ đề (A6).":"Sets, lists and cancels a watch: a market series level, or a topic (A6).",
"Hướng dẫn sử dụng và cách tính; tài liệu người dùng tải lên; tìm trên web với câu hỏi đã che (A5).":"User guide and methods; documents users upload; web search with the masked question (A5).",
"Tin RSS trong danh sách trắng, qua các cổng, vào hộp tin của CIO mỗi 10 phút.":"Allowlisted RSS news, through the gates, into the CIO's news inbox every 10 minutes.",
"Khách hàng và danh mục (mã hoá theo cột), sự kiện, nhận định, cảnh báo, nhật ký kiểm toán.":"Clients and portfolios (column-encrypted), events, views, alerts, audit log.",
"Giá đóng cửa và chuỗi công khai, mỗi nguồn theo lịch riêng (F1).":"Closing prices and public series, each source on its own schedule (F1).",
"Hội thoại (mã hoá), việc ghi đang chờ, mục trí nhớ, việc theo dõi, lần tổng hợp.":"Conversations (encrypted), pending writes, memory items, watches, consolidations.",
"Hướng dẫn theo vai trò và trang, cách tính, thuật ngữ, tài liệu của từng người.":"Guides by role and page, methods, glossary, each person's documents.",
"Tìm kiếm web của OpenRouter: chỉ nhận câu hỏi đã che, trả về đường dẫn trích dẫn.":"OpenRouter web search: takes only the masked question, returns cited links.",
"Lệnh “Chạy Agent CIO” vào hàng đợi; mỗi 5 giây chạy việc cũ nhất, mỗi lần một việc (AI-13).":"“Run CIO agent” goes into a queue; every 5 seconds the oldest job runs, one at a time (AI-13).",
"Một sự kiện → bốn nhóm phân tích song song → thảo luận → tổng hợp 2–4 kịch bản (FR-301…303).":"One event → four analysis groups in parallel → debate → 2–4 scenarios combined (FR-301…303).",
"tin của sự kiện, nghiên cứu đã phát hành — không dữ liệu khách":"the event's news, published research — no client data",
"Kiểm tra nhận định trước khi duyệt, và lại khi CIO sửa (FR-303).":"Checks a view before approval, and again when the CIO edits it (FR-303).",
"nhận định và sự kiện — không dữ liệu khách":"the view and the event — no client data",
"Tóm tắt văn bản chính sách đã xác nhận nguồn, trích đúng điều khoản (FR-306).":"Summarises a source-confirmed policy document, quoting the exact articles (FR-306).",
"một văn bản chính sách — không danh mục, không dữ liệu khách":"one policy document — no portfolio, no client data",
"Sau mỗi lần tải thị trường và nhận tin: so điều kiện đang mở, báo một lần (A6).":"After each market load and news intake: checks open watches, alerts once (A6).",
"07:00 hằng ngày: cảnh báo chính sách, vĩ mô, hạ tầng cho từng khách hàng.":"07:00 daily: policy, macro and infrastructure alerts for each client.",
"Mỗi 5 phút: hội thoại nhàn rỗi 15 phút → tối đa 5 mục trí nhớ, kiểm như người dùng tự bảo nhớ (A6).":"Every 5 minutes: a conversation idle for 15 minutes → up to 5 memory items, checked as if the user asked to remember (A6).",
"hội thoại của chính người đó, chỉ nơi mô hình được đọc":"the person's own conversation, only where the model may read",
"02:30 hằng ngày: xoá hội thoại quá hạn lưu giữ (CIO cấu hình) và mục trí nhớ hết hạn (A4).":"02:30 daily: deletes conversations past retention (set by the CIO) and expired memory items (A4).",
"hỏi; xác nhận việc ghi":"ask; confirm writes",
