"sau mỗi lần tải: chuỗi của job":"after each load: the job's series",
"sau mỗi lần nhận tin: sự kiện đã duyệt":"after each news intake: approved events",
"báo một lần ở chuông":"alerts once at the bell",
"nhận định đã duyệt và danh mục → cảnh báo khách":"approved views and portfolios → client alerts",
